import{_ as e,o as i,c as a,ag as o}from"./chunks/framework.CHxxV8OH.js";const p=JSON.parse('{"title":"Visual Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"visual-dashboard.md","filePath":"visual-dashboard.md","lastUpdated":1775890242000}'),l={name:"visual-dashboard.md"};function r(s,t,n,d,c,g){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="visual-dashboard" tabindex="-1">Visual Dashboard <a class="header-anchor" href="#visual-dashboard" aria-label="Permalink to &quot;Visual Dashboard&quot;">​</a></h1><p>The Agent Studio dashboard is where you spend most of your time. It&#39;s designed for clarity, speed, and confidence at scale.</p><h2 id="layout-overview" tabindex="-1">Layout Overview <a class="header-anchor" href="#layout-overview" aria-label="Permalink to &quot;Layout Overview&quot;">​</a></h2><p>The dashboard has three main regions:</p><p><strong>Sidebar Rail</strong> (left)</p><ul><li>Quick Actions (templates, import, export)</li><li>Views: Agents, Workflows, Capabilities, Templates</li><li>Search and filter across all entities</li></ul><p><strong>Main Canvas</strong> (center/right)</p><ul><li>Context-sensitive editor based on what you selected</li><li>Agent Builder, Workflow Editor, Capability Inspector, Handoff Graph</li><li>Live <code>.agent.md</code> and workflow <code>.json</code> previews</li></ul><p><strong>Bottom Inspector</strong> (optional)</p><ul><li>Details pane for the selected agent or capability</li><li>Relationships, recent edits, usage stats</li></ul><h2 id="agent-builder-tab" tabindex="-1">Agent Builder Tab <a class="header-anchor" href="#agent-builder-tab" aria-label="Permalink to &quot;Agent Builder Tab&quot;">​</a></h2><p>Create and edit agents visually.</p><p><strong>Identity</strong></p><ul><li>Agent name and emoji</li><li>One-line role description</li><li>Background color for visual distinction</li><li>Created/edited timestamps</li></ul><p><strong>Instructions</strong></p><ul><li>Rich markdown editor with live preview</li><li>Format agents with headers, lists, tables</li><li>Copy-paste instructions from docs</li><li>Character count and word count</li></ul><p><strong>Capabilities</strong></p><ul><li>Search bar to find Tools, Skills, MCP servers (fuzzy matching)</li><li>Add by clicking; drag to reorder</li><li>See descriptions and usage counts</li><li>Identify which other agents use the same tool</li></ul><p><strong>Handoffs</strong></p><ul><li>List all agents this agent can delegate to</li><li>Mark as &quot;requires approval&quot; for human-in-the-loop</li><li>Set constraints: max retries, timeout, fallback behavior</li><li>See the Handoff Graph visualization</li></ul><p><strong>Context</strong></p><ul><li>Show inherited instructions from Skills or MCP servers</li><li>Read-only reference for what this agent actually &quot;knows&quot;</li><li>Helps debug capability mismatches</li></ul><h2 id="handoff-graph" tabindex="-1">Handoff Graph <a class="header-anchor" href="#handoff-graph" aria-label="Permalink to &quot;Handoff Graph&quot;">​</a></h2><p>Interactive visualization of agent relationships.</p><p><strong>Controls</strong></p><ul><li><strong>Zoom</strong>: Scroll wheel or pinch on trackpad</li><li><strong>Pan</strong>: Click and drag the canvas</li><li><strong>Minimap</strong>: Bottom-right corner shows you where you are in large graphs</li><li><strong>Search</strong>: Cmd/Ctrl+F to highlight agents by name</li><li><strong>Focus</strong>: Double-click an agent to center and zoom</li></ul><p><strong>Node Details</strong></p><ul><li>Hover over an agent to see its role and capability count</li><li>Color coding: green = healthy, yellow = missing capabilities, red = no capabilities</li><li>Size reflects complexity (number of handoffs and capabilities)</li></ul><p><strong>Edges (Handoff Flows)</strong></p><ul><li>Solid lines = direct delegation</li><li>Dashed lines = conditional delegation</li><li>Arrow direction shows flow direction</li><li>Hover to see delegation constraints</li></ul><p><strong>Actions</strong></p><ul><li>Right-click an agent to edit or delete</li><li>Right-click an edge to modify handoff rules</li><li>Drag agents to rearrange (optional; resets to auto-layout on refresh)</li></ul><h2 id="capabilities-inspector" tabindex="-1">Capabilities Inspector <a class="header-anchor" href="#capabilities-inspector" aria-label="Permalink to &quot;Capabilities Inspector&quot;">​</a></h2><p>See exactly which agents use which tools, skills, and MCP servers.</p><p><strong>Tools Section</strong></p><ul><li>List all registered tools in the workspace</li><li>For each tool: agent assignments, last used, description</li><li>Filter by agent or by tool category</li><li>Add or remove tool registrations</li></ul><p><strong>Skills Section</strong></p><ul><li>All .skills directories registered in VS Code settings</li><li>Browse skills with descriptions and metadata</li><li>See which agents inherit each skill</li><li>Create new skill templates</li></ul><p><strong>MCP Servers Section</strong></p><ul><li>View all MCP servers currently active</li><li>Connection status (connected, connecting, error)</li><li>Endpoints and resource types</li><li>Link or unlink from agents</li></ul><p><strong>Gap Detection</strong></p><ul><li>Red-highlighted tools/skills are orphaned (no agents use them)</li><li>Blue-highlighted are high-value (used by 5+ agents)</li><li>Helps optimize and clean up unused capability registrations</li></ul><h2 id="workflow-editor" tabindex="-1">Workflow Editor <a class="header-anchor" href="#workflow-editor" aria-label="Permalink to &quot;Workflow Editor&quot;">​</a></h2><p>Build multi-agent workflows visually.</p><p><strong>Canvas Elements</strong></p><ul><li><strong>Step cards</strong>: Each agent appears as a draggable card</li><li><strong>Connectors</strong>: Click and drag from one step to another to create sequence</li><li><strong>Branch nodes</strong>: Add parallel execution points</li><li><strong>Condition nodes</strong>: Route based on output properties (optional)</li><li><strong>Entry point</strong>: Mark where workflow execution starts</li><li><strong>Exit point</strong>: Mark where results are collected</li></ul><p><strong>Sidebar for This Workflow</strong></p><ul><li>Workflow name and description</li><li>List of steps in order</li><li>Trigger configuration (manual, webhook, schedule)</li><li>Output schema expected from the final step</li></ul><p><strong>Run Panel</strong></p><ul><li>Input parameters for the workflow</li><li>Run button triggers execution through VS Code chat</li><li>Live execution log as agents execute</li><li>Final output display</li></ul><h2 id="dashboard-home" tabindex="-1">Dashboard Home <a class="header-anchor" href="#dashboard-home" aria-label="Permalink to &quot;Dashboard Home&quot;">​</a></h2><p>Your control center when Agent Studio opens.</p><p><strong>Quick Stats Cards</strong></p><ul><li>Total agents, active workflows, capability coverage</li><li>Last 3 agents edited (jump to them)</li><li>Next scheduled workflows</li></ul><p><strong>Activity Stream</strong></p><ul><li>Recent agent edits across your team</li><li>Workflow runs in the past 24 hours</li><li>Capability changes and tool registrations</li></ul><p><strong>Quick Actions Menu</strong></p><ul><li>Create new agent</li><li>Create new workflow</li><li>Import agents from file</li><li>Export all as <code>.tar.gz</code></li><li>Access workspace settings</li></ul><p><strong>Search and Filter</strong></p><ul><li>Global search: Cmd/Ctrl+P searches all agents, workflows, and capabilities</li><li>Filter by tag: #python, #api, #data</li><li>Sort by: recently edited, alphabetical, complexity</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Focus search</td><td>Cmd/Ctrl+P</td></tr><tr><td>New agent</td><td>Cmd/Ctrl+N</td></tr><tr><td>New workflow</td><td>Cmd/Ctrl+Shift+W</td></tr><tr><td>Save</td><td>Cmd/Ctrl+S</td></tr><tr><td>Zoom in (graph)</td><td>Cmd/Ctrl+=</td></tr><tr><td>Zoom out (graph)</td><td>Cmd/Ctrl+-</td></tr><tr><td>Jump to agent</td><td>Cmd/Ctrl+J, then type name</td></tr><tr><td>Format markdown</td><td>Cmd/Ctrl+Shift+F</td></tr></tbody></table><h2 id="performance-and-scaling" tabindex="-1">Performance and Scaling <a class="header-anchor" href="#performance-and-scaling" aria-label="Permalink to &quot;Performance and Scaling&quot;">​</a></h2><p>Agent Studio is optimized for:</p><ul><li><strong>3–50 agents</strong>: Instant responsiveness, all features available</li><li><strong>50–200 agents</strong>: Virtualized lists (only visible items render), graph rendering optimized</li><li><strong>200+ agents</strong>: Recommend workspaces organized into modules; Agent Studio groups by workspace root</li></ul><p>Graph rendering uses Canvas for performance. Real-time updates are debounced to prevent jank.</p><hr><p><strong><a href="/agent-studio/features">← Features</a></strong> | <strong><a href="/agent-studio/getting-started">Get Started →</a></strong></p>',68)])])}const h=e(l,[["render",r]]);export{p as __pageData,h as default};
